// @generated by tools/extract/extract.py — bodies copied verbatim from index.html
import { ACTIVITY_LEVELS, AGE_RANGE, HEIGHT_CM_RANGE, WEIGHT_KG_RANGE } from "../domain/body.js";
import { bmrFromBody } from "../domain/group1.js";
import { defaultActivityKey, dietGoalKeyFromText } from "../domain/group2.js";
import { inRange, isAutoAssessmentNote, leanMassKgFrom, macroTargetsFromCalories } from "../domain/group3.js";
import { waterTargetMlFromWeight } from "../domain/group4.js";
import { DIET_GOAL_CAL_MULT } from "../domain/nutrition.js";
import { sb } from "../platform/supabase.js";
import { todayISO } from "../shared/lib/dates.js";
import { fetchAssessmentHistory } from "./group1.js";

  // Recomputes and stores a client's BMR + daily calorie/macro targets from
  // their current body stats (bmrFromBody + macroTargetsFromCalories — same
  // formulas used everywhere else in the app). Call this any time weight,
  // height, age, gender, days/week, or goal changes on a client's profile —
  // whether the client edits it themselves or a trainer/manager edits it for
  // them — so Energy Balance and Daily targets never go stale after just the
  // weight number changes (Sept 6 2026 — Jimmy: a client updated her weight
  // and her BMR "didn't calculate," i.e. it never recalculated from the new
  // number; before this, BMR/targets were only ever computed once, at
  // signup). Best-effort and silent on failure/incomplete data — this is a
  // background refresh, never something that should block or error out the
  // profile edit that triggered it.
  // Sept 6 2026 — added a real return value + error surfacing after a trainer
  // reported gender/weight/height/birthday were all on file and the BMR still
  // never appeared: the inserts below used to be fire-and-forget with zero
  // error handling, so an RLS denial or any other DB error would fail this
  // completely silently — nothing in the UI, nothing in the console. Callers
  // that care (maybeRecalcBmr) can now show the real reason instead of just
  // "nothing happened."
  async function recalcBmrAndTargets(userId, clientName, stats) {
    if (!sb || !userId) return { ok: false, reason: "no_session" };
    const w = Number(stats.weight), h = Number(stats.height), a = Number(stats.age);
    if (!w || !h || !a) return { ok: false, reason: "incomplete" }; // not enough on file yet to calculate anything
    if (!inRange(w, WEIGHT_KG_RANGE) || !inRange(h, HEIGHT_CM_RANGE) || !inRange(a, AGE_RANGE)) return { ok: false, reason: "out_of_range" }; // clearly bad data — don't turn it into a nonsense BMR
    const gender = stats.gender || "Prefer not to say";
    // Sept 9 2026, Jimmy: "here the bmr is 1895 in assessment history and
    // its 1658 in calculations i want when i enter a bmr on the assessment
    // to take this one if i dont enter to calculate it." Root cause: this
    // function's own auto-recalculated rows (note "Auto-recalculated after
    // a profile update") were being picked up by the "latest assessment"
    // lookup below just like a real manual entry — but an auto row never
    // carries body_fat_pct/muscle_mass_kg, so the moment one of THIS
    // function's own rows became the newest, the real body-fat reading
    // (and any manually-typed BMR) silently stopped being carried forward,
    // and every later recalculation quietly fell back to the plain
    // weight-only formula instead of the person's real measured numbers —
    // exactly this class of regression the Sept 6 2026 fix below was meant
    // to prevent, just not proofed against this function's own writes.
    // Now looks specifically for the latest MANUALLY-entered assessment
    // (excluding this function's own auto-recalc rows) for both the
    // body-fat%/muscle-mass carry-forward AND the BMR itself — a real
    // manually-entered BMR (smart scale, DEXA scan) is used as-is and never
    // silently overwritten by the formula; only when nothing manual has
    // ever been entered does this fall back to calculating one.
    // Sept 9 2026, round 4: see fetchAssessmentHistory/isAutoAssessmentNote
    // above for the full story — this now matches "manual" in plain JS
    // against BOTH known auto-generated note strings, not just one, and a
    // weight-only log (real row, but no bmr on it) still can't shadow an
    // older row that actually has a bmr value.
    // Sept 10 2026, Jimmy — final call after this locked more than one real
    // client's BMR to a stale number no weight edit could ever move again:
    // a typed-in BMR still always wins against a passive weight-only LOG in
    // the Assessments form (that gate lives at the call site in
    // AssessmentPanel.handleSave, untouched by this), but an explicit "Edit
    // profile" edit — weight, height, age, or gender — is a deliberate
    // correction and now ALWAYS produces a fresh, live number here, full
    // stop, even if an old manual BMR is sitting in this client's history.
    // Only the lean-mass/body-fat% carry-forward below still looks at the
    // latest manual entry — that's a real measurement worth reusing, not a
    // frozen number that silently overrides everything after it.
    const history = await fetchAssessmentHistory(userId);
    const latestManual = history.find((r) => !isAutoAssessmentNote(r.note)) || null;
    const leanMassKg = latestManual ? leanMassKgFrom(w, latestManual.body_fat_pct, latestManual.muscle_mass_kg) : null;
    const bmr = Math.round(bmrFromBody(w, h, a, gender, leanMassKg));
    // Sept 10 2026, round 6 — the actual root cause of "still frozen" after
    // three rounds of otherwise-correct fixes: this used to INSERT a brand
    // new row every single time a profile field changed. assessed_on is a
    // DATE column, so a client whose weight got edited/tested several
    // times in one day (extremely common this session) ended up with
    // several auto-recalculated rows all dated today, with no reliable way
    // for any query to say which one is "the" latest — the display could
    // keep landing on an old same-day row's stale number even though a
    // fresh, correct one had already been written minutes earlier. Fixed
    // by updating today's existing auto row IN PLACE instead of inserting
    // another one, and clearing out any duplicate same-day auto rows left
    // over from before this fix existed — so from here on a given client
    // only ever has ONE auto row per day, no ties, nothing to guess about.
    // A manually-entered row for today (real measurement/typed BMR) is
    // never touched here — a fresh auto row is simply not needed once a
    // real one exists for today.
    const todaysAutoRows = history.filter((r) => r.assessed_on === todayISO() && isAutoAssessmentNote(r.note));
    let assessErr = null;
    if (todaysAutoRows.length > 0) {
      const keep = todaysAutoRows[0];
      const { error } = await sb.from("body_assessments").update({
        weight_kg: w, bmr, note: "Auto-recalculated after a profile update"
      }).eq("id", keep.id);
      assessErr = error;
      if (!error && todaysAutoRows.length > 1) {
        const staleIds = todaysAutoRows.slice(1).map((r) => r.id);
        await sb.from("body_assessments").delete().in("id", staleIds);
      }
    } else {
      const { error } = await sb.from("body_assessments").insert([{
        user_id: userId, client_name: clientName, assessed_on: todayISO(),
        weight_kg: w, bmr, note: "Auto-recalculated after a profile update"
      }]);
      assessErr = error;
    }
    if (assessErr) {
      console.error("recalcBmrAndTargets: body_assessments insert/update failed", assessErr);
      return { ok: false, reason: "db_error", error: assessErr };
    }
    // Same training-days -> activity-tier logic as the self-train signup
    // form, including its "day-to-day active" bump (desk job vs on your
    // feet all day) — previously this recalculation only ever used the
    // plain days/week tier, so anyone who'd told the app they're active
    // day-to-day lost that bump the moment anything else on their profile
    // changed. stats.activeLifestyle is optional — omitted callers (most of
    // them) behave exactly as before.
    const trainingTierIdx = ACTIVITY_LEVELS.findIndex((lvl) => lvl.key === defaultActivityKey(Number(stats.daysPerWeek) || 3));
    const bumpedIdx = stats.activeLifestyle === "active" ? Math.min(trainingTierIdx + 1, ACTIVITY_LEVELS.length - 1) : trainingTierIdx;
    const activityMult = ACTIVITY_LEVELS[Math.max(bumpedIdx, 0)].mult;
    const dietGoalMult = DIET_GOAL_CAL_MULT[dietGoalKeyFromText(stats.goal)];
    const targetCalories = Math.round(bmr * activityMult * dietGoalMult);
    const targets = macroTargetsFromCalories(targetCalories, w, gender, leanMassKg);
    const { error: targetsErr } = await sb.from("diet_plans").upsert([{
      user_id: userId, client_name: clientName,
      calories_target: targets.calories, protein_target: targets.protein, carbs_target: targets.carbs, fat_target: targets.fat,
      water_target_ml: waterTargetMlFromWeight(w)
    }], { onConflict: "user_id" });
    if (targetsErr) {
      console.error("recalcBmrAndTargets: diet_plans upsert failed", targetsErr);
      return { ok: false, reason: "db_error", error: targetsErr };
    }
    return { ok: true, bmr, targetCalories };
  }

export { recalcBmrAndTargets };
